using System;using System.IO;using System.Collections;using System.Collections.Generic;using UnityEngine;
public static class PortInterstellarAudit {
 [Serializable] class Report {public string phase,saveName,scope="Independent fixtures grant technology, buildings, stock, ships and initial energy. Dispatch, warp, delivery, return and post-load simulation use original game ticks; no manual UI placement claim.";public int sourcePlanet,targetPlanet,sourceGid,targetGid,carry,total,sourceCount,targetCount,flying,idle,warpers;public long tick;public double lightYears;public bool sawFlight,sawWarp,reloadedInFlight,firstDelivery,secondDelivery;public List<string> errors=new List<string>();}
 static Report r;public static bool Passed{get;private set;}static string Folder=>Application.persistentDataPath;static StationComponent A=>GameMain.data.galacticTransport.stationPool[r.sourceGid];static StationComponent B=>GameMain.data.galacticTransport.stationPool[r.targetGid];
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static void Write(string phase){r.phase=phase;r.tick=GameMain.gameTick;if(r.sourceGid>0&&r.targetGid>0){r.sourceCount=A.storage[0].count;r.targetCount=B.storage[0].count;r.flying=A.workShipCount;r.idle=A.idleShipCount;r.warpers=A.warperCount;}File.WriteAllText(Path.Combine(Folder,"interstellar-audit.json"),JsonUtility.ToJson(r,true));File.AppendAllText(Path.Combine(Folder,"interstellar-audit.txt"),JsonUtility.ToJson(r)+"\n");}
 static StationComponent Build(PlanetFactory f,Vector3 pos){var item=LDB.items.Select(2104);var p=pos.normalized*(f.planet.realRadius+.2f);var pre=new PrebuildData{protoId=2104,modelIndex=(short)item.ModelIndex,pos=p,rot=Quaternion.FromToRotation(Vector3.up,p.normalized),itemRequired=0};int id=f.AddPrebuildDataWithComponents(pre);f.BuildFinally(GameMain.mainPlayer,id,true,false);for(int i=1;i<f.entityCursor;i++)if(f.entityPool[i].id==i&&f.entityPool[i].protoId==2104&&(f.entityPool[i].pos-p).sqrMagnitude<.01f)return f.transport.stationPool[f.entityPool[i].stationId];throw new Exception("Station fixture build failed");}
 static IEnumerator Capture(string tag){yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();try{File.WriteAllBytes(Path.Combine(Folder,"interstellar-"+tag+".png"),t.EncodeToPNG());}finally{UnityEngine.Object.Destroy(t);}yield return null;}
 static int Cargo(){int v=A.storage[0].count+B.storage[0].count;for(int i=0;i<A.workShipCount;i++)v+=A.workShipDatas[i].itemCount;return v;}
 static void Observe(){r.sawFlight|=A.workShipCount>0;for(int i=0;i<A.workShipCount;i++)r.sawWarp|=A.workShipDatas[i].warpState>.01f;Check(Cargo()==r.total,"Cargo conservation failed: "+Cargo()+" / "+r.total);}
 static IEnumerator Run(){
  Passed=false;r=new Report();File.WriteAllText(Path.Combine(Folder,"interstellar-audit.txt"),r.scope+"\n");Write("setup");var home=GameMain.localPlanet;PlanetData target=null;double closest=double.MaxValue;foreach(var star in GameMain.galaxy.stars){if(star.id==home.star.id)continue;double d=(star.uPosition-home.star.uPosition).sqrMagnitude;if(d>=closest)continue;foreach(var p in star.planets)if(p.type!=EPlanetType.Gas){target=p;closest=d;break;}}
  Check(target!=null,"No target planet");r.sourcePlanet=home.id;r.targetPlanet=target.id;r.lightYears=Math.Sqrt(closest)/2400000.0;
  TechProto warp=null;foreach(var tech in LDB.techs.dataArray)if(tech.UnlockFunctions!=null&&Array.IndexOf(tech.UnlockFunctions,17)>=0){warp=tech;break;}Check(warp!=null,"No original ship warp technology");GameMain.history.UnlockTechUnlimitedWithAllPre(warp.ID);Check(GameMain.history.logisticShipWarpDrive,"Original warp tech failed");
  var remote=GameMain.data.GetOrCreateFactory(target);var a=Build(home.factory,GameMain.mainPlayer.position+Vector3.Cross(GameMain.mainPlayer.position.normalized,Vector3.up)*35);var b=Build(remote,Vector3.up);r.sourceGid=a.gid;r.targetGid=b.gid;Check(a.isStellar&&b.isStellar&&a.planetId/100!=b.planetId/100,"Not a cross-star pair");r.carry=GameMain.history.logisticShipCarries;r.total=r.carry*2;
  home.factory.transport.SetStationStorage(a.id,0,1101,r.total,ELogisticStorage.None,ELogisticStorage.Supply,GameMain.mainPlayer);remote.transport.SetStationStorage(b.id,0,1101,r.carry,ELogisticStorage.None,ELogisticStorage.Demand,GameMain.mainPlayer);a.storage[0].count=r.total;a.idleShipCount=1;a.energy=a.energyMax;b.energy=b.energyMax;a.warperCount=10;GameMain.data.galacticTransport.RefreshTraffic();Write("waiting_dispatch");
  float deadline=Time.realtimeSinceStartup+90;while(A.workShipCount==0&&Time.realtimeSinceStartup<deadline)yield return new WaitForSecondsRealtime(.25f);Check(A.workShipCount==1,"No original dispatch");Observe();Write("in_flight_before_save");yield return Capture("departing");
  r.saveName="PortInterstellar-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Check(GameSave.SaveCurrentGame(r.saveName),"In-flight save failed");yield return null;DSPGame.StartGame(r.saveName);Write("reloading");yield return null;deadline=Time.realtimeSinceStartup+180;
  while((!GameMain.isRunning||DSPGame.IsMenuDemo||GameMain.localPlanet==null||!GameMain.localPlanet.factoryLoaded)&&Time.realtimeSinceStartup<deadline)yield return new WaitForSecondsRealtime(1);Check(GameMain.isRunning&&!DSPGame.IsMenuDemo&&GameMain.localPlanet!=null&&GameMain.localPlanet.factoryLoaded,"Reload timed out");r.reloadedInFlight=A.workShipCount==1&&Cargo()==r.total;Check(r.reloadedInFlight,"In-flight ship/cargo not preserved");Write("in_flight_reloaded");
  UIRoot.instance.uiGame.OpenStarmapWithCurrentLocation();yield return new WaitForSecondsRealtime(2);yield return Capture("starmap");UIRoot.instance.uiGame.starmap._Close();yield return null;
  deadline=Time.realtimeSinceStartup+600;float logAt=0;bool cap=false;while((B.storage[0].count<r.carry||A.workShipCount>0)&&Time.realtimeSinceStartup<deadline){yield return new WaitForSecondsRealtime(.5f);Observe();if(Time.realtimeSinceStartup>logAt){Write("first_route");logAt=Time.realtimeSinceStartup+10;}if(r.sawWarp&&!cap){cap=true;yield return Capture("warping");}}
  Observe();r.firstDelivery=B.storage[0].count==r.carry&&A.storage[0].count==r.carry&&A.workShipCount==0&&A.idleShipCount==1&&r.sawWarp;Write("first_route_finished");Check(r.firstDelivery,"First warp delivery/return incomplete");
  GameMain.galaxy.PlanetById(r.targetPlanet).factory.transport.SetStationStorage(B.id,0,1101,r.total,ELogisticStorage.None,ELogisticStorage.Demand,GameMain.mainPlayer);GameMain.data.galacticTransport.RefreshTraffic();deadline=Time.realtimeSinceStartup+600;
  while((B.storage[0].count<r.total||A.workShipCount>0)&&Time.realtimeSinceStartup<deadline){yield return new WaitForSecondsRealtime(.5f);Observe();if(Time.realtimeSinceStartup>logAt){Write("second_route");logAt=Time.realtimeSinceStartup+10;}}
  Observe();r.secondDelivery=B.storage[0].count==r.total&&A.storage[0].count==0&&A.workShipCount==0&&A.idleShipCount==1;Check(r.secondDelivery,"Second delivery/return incomplete");Check(A.warperCount==6,"Expected four warpers consumed for two round trips");Check(GameSave.SaveCurrentGame(r.saveName+"-Delivered"),"Completed route save failed");Passed=true;Write("passed");yield return Capture("completed");
 }
 public static IEnumerator SafeRun(){var run=Run();while(true){object next=null;bool more=false;Exception err=null;try{more=run.MoveNext();if(more)next=run.Current;}catch(Exception e){err=e;}if(err!=null){r.errors.Add(err.ToString());Write("failed");Debug.LogError("Interstellar audit: "+err);break;}if(!more)break;yield return next;}((IDisposable)run).Dispose();}
}
